/// Whether [path] is inside the browser's visible scroll viewport.
///
/// Used for Linux-only conditional UI so we only expose the action when the
/// row is genuinely off-screen (e.g. swipe-up browser collapsed).
bool isTrackVisible(String path) {
  final tracks = ctrl.tracks;
  final index = tracks.indexWhere((t) => t.path == path);
  if (index < 0) return true;
  if (!scroll.hasClients) return true;

  final viewport = scroll.position.viewportDimension;
  if (viewport <= 0) return false;

  final pos = scroll.position;
  // With reverse: true, offset 0 is the visual bottom.
  final hasUp = ctrl.currentPath != null ? 1 : 0;
  final childIndex = hasUp + (tracks.length - 1 - index);
  final rowHeight = Theme.of(context).extension<AppGeometry>()!.rowHeight;

  final rowTop = childIndex * rowHeight;
  final rowBottom = rowTop + rowHeight;

  final visibleTop = pos.pixels;
  final visibleBottom = visibleTop + viewport;

  return rowBottom > visibleTop && rowTop < visibleBottom;
}

edits.newText:
/// Whether [path] is currently inside the browser's visible region.
///
/// This is used for Linux-only conditional UI so we only expose the action
/// when the row is genuinely off-screen (e.g. swipe-up browser collapsed).
///
/// We rely on render-box geometry instead of scroll offsets because the
/// swipe-up browser can slide off-screen while the scroll viewport still
/// reports a non-zero size.
bool isTrackVisible(String path) {
  if (!scroll.hasClients) return false;

  final rowContext = rowKeys[path]?.currentContext;
  if (rowContext == null) return false;

  final rowBox = rowContext.findRenderObject();
  if (rowBox is! RenderBox || !rowBox.hasSize) return false;

  final viewportContext = scroll.position.context.storageContext;
  final viewportBox = viewportContext.findRenderObject();
  if (viewportBox is! RenderBox || !viewportBox.hasSize) return false;

  final rowRect = rowBox.localToGlobal(Offset.zero) & rowBox.size;
  final viewportRect =
      viewportBox.localToGlobal(Offset.zero) & viewportBox.size;

  return rowRect.overlaps(viewportRect);
}

